import csv
from pathlib import Path


class MINSTD:
    def __init__(self, seed):
        self.state = seed

    def draw(self):
        self.state = (48271 * self.state) % 2147483647
        return self.state

    def shuffle(self, values):
        for i in range(len(values), 1, -1):
            j = self.draw() % i
            values[i - 1], values[j] = values[j], values[i - 1]


def read_images(path):
    with open(path, encoding="ascii", newline="") as handle:
        rows = list(csv.reader(handle))[1:]
    return [
        {
            "id": identifier, "label": int(label),
            "pixels": pixels,
            "vector": [float(digit) for digit in pixels],
        }
        for identifier, label, pixels in rows
    ]


def read_architectures(path="input/network.txt"):
    text = Path(path).read_text(encoding="ascii").strip()
    dimensions, *blocks = text.split("\n\n")
    _, width, height = dimensions.split()
    width, height = int(width), int(height)
    networks = []
    for block in blocks:
        lines = block.splitlines()
        name = lines[0].split()[1]
        layers = []
        for line in lines[1:]:
            kind, units, activation = line.split()
            layers.append({
                "units": int(units),
                "activation": activation,
                "kind": kind,
            })
        networks.append({
            "name": name, "layers": layers,
            "width": width, "height": height,
            "classes": layers[-1]["units"],
        })
    return networks


def read_weights(networks, path="input/weights.txt"):
    blocks = Path(path).read_text(encoding="ascii").strip().split("\n\n")
    results = {}
    for network, block in zip(networks, blocks):
        lines = block.splitlines()
        cursor = 1
        theta = []
        for _ in network["layers"]:
            _, layer_number, rows, columns = lines[cursor].split()
            cursor += 1
            for _ in range(int(rows)):
                weights = lines[cursor].split()
                theta.extend(float(value) for value in weights[1:])
                cursor += 1
            biases = lines[cursor].split()
            theta.extend(float(value) for value in biases[1:])
            cursor += 1
        results[network["name"]] = theta
    return results


def read_settings(path="input/params.txt"):
    settings = {"runs": []}
    for line in Path(path).read_text(encoding="ascii").splitlines():
        kind, *items = line.split()
        if kind == "RUN":
            name, network, optimizer, rate, decay, *extra = items
            settings["runs"].append({
                "name": name, "network": network, "optimizer": optimizer,
                "rate": float(rate), "decay": float(decay),
                "extra": list(map(float, extra)),
            })
        elif kind == "LR_STEP":
            settings["lr_step"] = int(items[0])
            settings["lr_gamma"] = float(items[1])
        elif kind in ("PRUNE", "NOISE"):
            settings[kind.lower()] = list(map(int, items))
        else:
            key = {
                "SEED": "seed", "BATCH_SIZE": "batch_size",
                "MAX_EPOCHS": "max_epochs", "PATIENCE": "patience",
                "GRADIENT_CHECK_STRIDE": "gradient_stride",
                "CALIBRATION_BINS": "calibration_bins",
            }[kind]
            settings[key] = int(items[0])
    return settings


def load_inputs():
    networks = read_architectures()
    return {
        "train": read_images("input/train.csv"),
        "test": read_images("input/test.csv"),
        "networks": networks,
        "weights": read_weights(networks),
        "settings": read_settings(),
    }

from collections import Counter


def real(value, places):
    result = f"{value:.{places}f}"
    return result[1:] if result.startswith("-") and float(result) == 0 else result


def ratio(numerator, denominator):
    if denominator == 0:
        return "-"
    rounded = (20000 * numerator + denominator) // (2 * denominator)
    return f"{rounded // 10000}.{rounded % 10000:04d}"


def best_two(scores):
    return sorted(
        range(len(scores)), key=lambda index: (-scores[index], index)
    )[:2]


def confusion(outcomes, classes):
    table = [[0] * classes for _ in range(classes)]
    for outcome in outcomes:
        table[outcome["label"]][outcome["predicted"]] += 1
    return table


def class_measures(table, klass):
    support = sum(table[klass])
    predicted = sum(row[klass] for row in table)
    true = table[klass][klass]
    return {
        "support": support, "predicted": predicted,
        "precision": ratio(true, predicted),
        "recall": ratio(true, support),
        "f1": ratio(2 * true, support + predicted),
    }


def level_maps(levels, width, height):
    return [
        " ".join(
            "".join(str(level[row * width + column])
                    for column in range(width))
            for level in levels
        ) for row in range(height)
    ]


def ascii_image(pixels, width):
    return [
        "".join("#" if pixel == "1" else "." for pixel in pixels[i:i + width])
        for i in range(0, len(pixels), width)
    ]


def binary_frequency(images, label, pixels):
    chosen = [image for image in images if image["label"] == label]
    if not chosen:
        return [0] * pixels
    return [
        min(9, (10 * sum(image["pixels"][i] == "1"
                         for image in chosen)) // len(chosen))
        for i in range(pixels)
    ]

import math


def hidden_activation(kind, value):
    if kind == "TANH":
        return math.tanh(value)
    if kind == "SIGMOID":
        return 1.0 / (1.0 + math.exp(-value))
    return value if value > 0 else 0.0


def hidden_derivative(kind, z, activated):
    if kind == "TANH":
        return 1 - activated * activated
    if kind == "SIGMOID":
        return activated * (1 - activated)
    return 1.0 if z > 0 else 0.0


def output_scores(kind, z, label):
    count = len(z)
    if kind == "SOFTMAX":
        maximum = max(z)
        terms = [math.exp(value - maximum) for value in z]
        total = sum(terms)
        scores = [value / total for value in terms]
        loss = math.log(total) - (z[label] - maximum)
        error = [
            value - (1.0 if k == label else 0.0)
            for k, value in enumerate(scores)
        ]
        return scores, loss, error
    scores = [1 / (1 + math.exp(-value)) for value in z]
    error = []
    loss = 0.0
    for k, value in enumerate(scores):
        target = 1.0 if k == label else 0.0
        residual = value - target
        loss += residual * residual
        error.append(2 * residual * value * (1 - value) / count)
    return scores, loss / count, error


def weighted_pre_activation(weights, biases, activation):
    result = []
    for row, bias in zip(weights, biases):
        weighted = sum(
            coefficient * input_value
            for coefficient, input_value in zip(row, activation)
        )
        result.append(weighted + bias)
    return result


def backward_sum(weights, output_error):
    return [
        sum(row[column] * error
            for row, error in zip(weights, output_error))
        for column in range(len(weights[0]))
    ]

from layers import (
    backward_sum, hidden_activation, hidden_derivative,
    output_scores, weighted_pre_activation,
)


def layout_for(architecture):
    previous = architecture["width"] * architecture["height"]
    layout = []
    weights_mask = []
    index = 0
    for definition in architecture["layers"]:
        outputs = definition["units"]
        weights = outputs * previous
        layer = {
            "inputs": previous, "outputs": outputs,
            "activation": definition["activation"], "kind": definition["kind"],
            "weight_start": index, "weight_end": index + weights,
            "bias_start": index + weights,
            "bias_end": index + weights + outputs,
        }
        layout.append(layer)
        weights_mask.extend([True] * weights + [False] * outputs)
        index += weights + outputs
        previous = outputs
    return {"layers": layout, "is_weight": weights_mask, "parameters": index,
            "weight_count": sum(weights_mask)}


def layer_values(theta, layer):
    width = layer["inputs"]
    flat = theta[layer["weight_start"]:layer["weight_end"]]
    weights = [
        flat[i * width:(i + 1) * width]
        for i in range(layer["outputs"])
    ]
    biases = theta[layer["bias_start"]:layer["bias_end"]]
    return weights, biases


def forward(architecture, layout, theta, image):
    activations = [image["vector"]]
    preactivations = []
    all_weights = []
    output_error = None
    loss = None
    scores = None
    last = len(layout["layers"]) - 1
    for index, layer in enumerate(layout["layers"]):
        weights, biases = layer_values(theta, layer)
        all_weights.append(weights)
        z = weighted_pre_activation(weights, biases, activations[-1])
        preactivations.append(z)
        if index == last:
            scores, loss, output_error = output_scores(
                layer["activation"], z, image["label"],
            )
            activations.append(scores)
        else:
            activations.append([
                hidden_activation(layer["activation"], value) for value in z
            ])
    return {
        "z": preactivations, "a": activations,
        "weights": all_weights, "scores": scores,
        "loss": loss, "output_delta": output_error,
    }


def gradient(architecture, layout, theta, image, input_gradient=False):
    cache = forward(architecture, layout, theta, image)
    layers = layout["layers"]
    deltas = [None] * len(layers)
    deltas[-1] = cache["output_delta"]
    for index in range(len(layers) - 2, -1, -1):
        propagated = backward_sum(
            cache["weights"][index + 1], deltas[index + 1]
        )
        layer = layers[index]
        deltas[index] = [
            value * hidden_derivative(
                layer["activation"], cache["z"][index][j],
                cache["a"][index + 1][j],
            )
            for j, value in enumerate(propagated)
        ]
    grad = [0.0] * layout["parameters"]
    for index, layer in enumerate(layers):
        destination = layer["weight_start"]
        for j in range(layer["outputs"]):
            for i in range(layer["inputs"]):
                grad[destination] = (
                    deltas[index][j] * cache["a"][index][i]
                )
                destination += 1
        for j in range(layer["outputs"]):
            grad[layer["bias_start"] + j] = deltas[index][j]
    if not input_gradient:
        return grad, cache
    original_gradient = backward_sum(cache["weights"][0], deltas[0])
    return grad, cache, original_gradient


def average_gradient(architecture, layout, theta, images):
    result = [0.0] * layout["parameters"]
    loss = 0.0
    for image in images:
        grad, cache = gradient(architecture, layout, theta, image)
        loss += cache["loss"]
        for i, value in enumerate(grad):
            result[i] += value
    count = len(images)
    return [value / count for value in result], loss / count


def evaluate(architecture, layout, theta, images):
    outcomes = []
    loss = 0.0
    correct = 0
    for image in images:
        cache = forward(architecture, layout, theta, image)
        scores = cache["scores"]
        prediction = max(range(len(scores)), key=lambda k: (scores[k], -k))
        outcome = {
            "id": image["id"], "label": image["label"],
            "predicted": prediction, "confidence": scores[prediction],
            "scores": scores, "loss": cache["loss"], "hidden": cache["a"][1:-1],
        }
        outcomes.append(outcome)
        loss += cache["loss"]
        correct += prediction == image["label"]
    return {
        "loss": loss / len(images), "correct": correct,
        "outcomes": outcomes,
    }

import math


def initialize(run, count):
    return {
        "momentum": [0.0] * count,
        "first": [0.0] * count, "second": [0.0] * count,
        "power1": 1.0, "power2": 1.0,
    }


def epoch_rate(run, epoch, step, gamma):
    rate = run["rate"]
    for _ in range((epoch - 1) // step):
        rate *= gamma
    return rate


def update(theta, grad, state, run, learning_rate):
    optimizer = run["optimizer"]
    if optimizer == "SGD":
        for index, value in enumerate(grad):
            theta[index] -= learning_rate * value
        return
    if optimizer == "MOMENTUM":
        mu = run["extra"][0]
        for index, value in enumerate(grad):
            velocity = mu * state["momentum"][index] + value
            state["momentum"][index] = velocity
            theta[index] -= learning_rate * velocity
        return
    beta1, beta2, epsilon = run["extra"]
    state["power1"] *= beta1
    state["power2"] *= beta2
    for index, value in enumerate(grad):
        first = beta1 * state["first"][index] + (1 - beta1) * value
        second = beta2 * state["second"][index] + (1 - beta2) * value * value
        state["first"][index] = first
        state["second"][index] = second
        corrected_first = first / (1 - state["power1"])
        corrected_second = second / (1 - state["power2"])
        theta[index] -= (
            learning_rate * corrected_first / (math.sqrt(corrected_second) + epsilon)
        )
